import {readFileSync, writeFileSync} from 'node:fs';
const root = new URL('../', import.meta.url);
const payload = Object.fromEntries([
  ['components', 'components.js'], ['engine', 'engine.js'], ['css', 'style.css']
].map(([key, name]) => [key, readFileSync(new URL(`src/${name}`, root), 'utf8')]));
writeFileSync(new URL('src/export-payload.js', root),
  '/* Generated by npm run build:exports. */\nwindow.M404_EXPORT=' + JSON.stringify(payload) + ';\n');
